const GBASE={
 '외관':{std:'눈으로 볼 때 손상·변형·오염·탈락이 없고 설치 당시 상태가 유지된다.',ng:'파손·변형·심한 오염·부식·탈락이 보인다.',steps:['해당 부위를 눈으로 자세히 본다.','이상이 있으면 가까이와 전체 사진을 찍는다.'],shot:'이상 부위 근접 + 전체'},
 '기능':{std:'기능을 직접 동작시켰을 때 즉시 정상 동작하고 오류·경고가 없다.',ng:'동작하지 않거나 늦다. 오류·경고가 뜬다.',steps:['기능을 직접 동작시켜 본다. (버튼·호출·접속 등)','반응·화면·소리를 확인한다.','오류가 나면 상황을 메모하고 사진을 남긴다.'],shot:'동작 결과 화면'},
 '안전':{std:'화재·감전·침수 등 사고로 이어질 위험 요소가 없다.',ng:'탄 흔적·누수·헐거운 배선 등 위험 요소가 있다.',steps:['위험 요소(열·물·전기)가 없는지 눈과 냄새·소리로 확인한다.'],shot:'위험 우려 부위'},
 '성능점검':{std:'확인·측정값이 설계도서·제조사 규격 이내이고 이상이 없다.',ng:'규격 범위를 벗어나거나 확인이 불가능하다.',steps:['점검 방법에 적힌 대로 확인 또는 측정한다.','값은 메모에 단위와 함께 적고, 화면·측정기를 사진으로 남긴다.'],shot:'측정기 또는 확인 화면'}
};
function guideFor(it){
  const g0=GUIDE.find(x=>x.m.test(it.t));const b=GBASE[it.cat]||GBASE['기능'];const g=Object.assign({},b,g0||{});
  if(!g0){const core=it.t.replace(/\(.*?\)/g,'').replace(/\s*(여부|상태|유무)?\s*(확인|점검|측정)\s*$/,'').trim();if(core)g.std=core+'이(가) 정상이고 이상이 없는 상태이다.';}
  return g;}

/* ---------- 유틸 ---------- */
const $=(s,e=document)=>e.querySelector(s);
function h(tag,attrs,...kids){const e=document.createElement(tag);
  for(const [k,v] of Object.entries(attrs||{})){
    if(k==='class')e.className=v;else if(k.startsWith('on'))e.addEventListener(k.slice(2),v);
    else if(v===true)e.setAttribute(k,'');else if(v!==false&&v!=null)e.setAttribute(k,v);}
  for(const c of kids.flat(Infinity)){if(c==null||c===false)continue;e.append(c.nodeType?c:document.createTextNode(String(c)));}
  return e;}
const clone=o=>JSON.parse(JSON.stringify(o));
const pad=n=>String(n).padStart(2,'0');
const ymd=d=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
const today=()=>ymd(new Date());
const uid=()=>'x'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const lsGet=k=>{try{return localStorage.getItem(k)||''}catch(e){return ''}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}};
function addMonths(s,n){const [y,m,d]=s.split('-').map(Number);const t=new Date(y,m-1+n,d);return t.getDate()!==d?new Date(y,m-1+n+1,0):t;}
const days=(a,b)=>Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/864e5);
const dlabel=n=>n>=0?'D-'+n:'D+'+(-n);
const areaOf=no=>AREAS.find(a=>a.no===no);
const itemsOf=(no,type)=>areaOf(no)[type];
const siteName=id=>(sites.find(s=>s.id===id)||{}).name||'(삭제된 현장)';

