const deployOn=()=>!!(acct&&acct.role==='admin'&&DEPLOY.mode==='onprem'&&DEPLOY.clientId);
const setDeploy=d=>{DEPLOY=d;lsSet('deploy',JSON.stringify(d));applyScope();renderNav();render();};
const myCo=()=>{if(!acct||acct.role!=='engineer')return '';if(acct.refType==='company')return acct.refId;if(acct.refType==='person')return(people.find(p=>p.id===acct.refId)||{}).companyId||'';return '';};
const loaded={cc:false,cb:false,s:false,i:false,x:false,c:false,p:false,k:false,a:false,m:false,l:false};
const CAP={write:false};let acct=null;
const ROLES={manager:{ko:'고객',en:'Client',d:'발주한 사이트의 점검 이력·이슈·리포트를 열람합니다.',ic:'eye'},
  engineer:{ko:'점검자',en:'Engineer',d:'현장 점검을 입력하고 보고서를 만듭니다.',ic:'check'},
  supervisor:{ko:'통합관리자',en:'Admin',d:'고객·점검업체·점검자·계정을 등록하고 전체를 관리합니다.',ic:'shield'}};
let roleKey='manager',entered=false;
function applyScope(){
  const co=myCo();
  if(acct&&acct.role==='client'){const ids=new Set(raw.sites.filter(x=>x.clientId===acct.refId).map(x=>x.id));
    sites=raw.sites.filter(x=>ids.has(x.id));insps=raw.insps.filter(x=>ids.has(x.siteId));issues=raw.issues.filter(x=>ids.has(x.siteId));clients=raw.clients.filter(k=>k.id===acct.refId);locations=raw.locs.filter(l=>ids.has(l.siteId));companies=raw.cos.filter(c=>c.clientId===acct.refId);}
  else if(co){const ids=new Set(raw.sites.filter(x=>x.ownerId===co).map(x=>x.id));
    sites=raw.sites.filter(x=>ids.has(x.id));insps=raw.insps.filter(x=>ids.has(x.siteId));issues=raw.issues.filter(x=>ids.has(x.siteId));clients=raw.clients.filter(k=>k.ownerId===co||sites.some(x=>x.clientId===k.id));locations=raw.locs.filter(l=>ids.has(l.siteId));companies=raw.cos;}
  else if(deployOn()){const ids=new Set(raw.sites.filter(x=>x.clientId===DEPLOY.clientId).map(x=>x.id)),k=raw.clients.find(x=>x.id===DEPLOY.clientId)||{};
    sites=raw.sites.filter(x=>ids.has(x.id));insps=raw.insps.filter(x=>ids.has(x.siteId));issues=raw.issues.filter(x=>ids.has(x.siteId));clients=raw.clients.filter(x=>x.id===DEPLOY.clientId);locations=raw.locs.filter(l=>ids.has(l.siteId));
    const cs=new Set(sites.map(x=>x.ownerId).filter(Boolean));if(k.ownerId)cs.add(k.ownerId);companies=raw.cos.filter(c=>c.clientId===DEPLOY.clientId||cs.has(c.id));}
  else{sites=raw.sites;insps=raw.insps;issues=raw.issues;clients=raw.clients;locations=raw.locs;companies=raw.cos;}}
async function sha(pw,salt){const t=salt+':'+pw;
  try{const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return [...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('');}
  catch(e){let v=5381;for(const c of t)v=((v<<5)+v+c.charCodeAt(0))|0;return 'f'+(v>>>0).toString(16);}}
