function dueInfo(site,type){
  if(!site.completed) return null;
  const step=type==='maint'?6:12; let k=0,start=site.completed;
  while(ymd(addMonths(site.completed,(k+1)*step))<=today()) k++;
  start=ymd(addMonths(site.completed,k*step)); const next=ymd(addMonths(site.completed,(k+1)*step));
  const done=insps.some(i=>i.siteId===site.id&&i.type===type&&i.status==='submitted'&&(i.date||'')>=start);
  return {start,next,done,dday:days(today(),next)};
}
