  if(!db){entered=true;setRole('로그인 필요');$('#app').replaceChildren(h('div',{class:'card'},'저장소에 연결할 수 없습니다. claude.ai에 로그인한 상태로 링크를 여세요.'));return;}
  CAP.write=user?user.can('data.write')!==false:false;
  $('#role').addEventListener('click',()=>{if(!entered)return;navTo('me');});
  $('#logout').addEventListener('click',()=>{if(entered)logout();});
  const sub=(name,key,assign,soft)=>db.collection(name).onSnapshot(s=>{assign(s.docs.map(d=>({id:d.id,...d.data()})));loaded[key]=true;refresh();},
     e=>{if(soft){assign([]);loaded[key]=true;refresh();return;}$('#app').replaceChildren(h('div',{class:'card err'},'데이터를 불러오지 못했습니다 ('+e.code+')'));});
  sub('sites','s',v=>{raw.sites=v;applyScope();});sub('inspections','i',v=>{raw.insps=v;applyScope();});sub('issues','x',v=>{raw.issues=v;applyScope();});
  sub('companies','c',v=>{raw.cos=v;applyScope();},true);sub('people','p',v=>{people=v;applyScope();},true);sub('clients','k',v=>{raw.clients=v;applyScope();},true);sub('accounts','a',v=>accounts=v,true);sub('memos','m',v=>memos=v,true);sub('locations','l',v=>{raw.locs=v;applyScope();},true);sub('cables','cb',v=>cables=v,true);sub('cabchecks','cc',v=>cabchecks=v,true);
  renderGate();
