function startSession(a,dpw){
  let nm=a.name||a.id;
  if(a.refType==='client'){const k=clients.find(x=>x.id===a.refId);if(k)nm=k.name;}
  if(a.refType==='person'){const p=people.find(x=>x.id===a.refId);if(p)nm=p.name;}
  if(a.refType==='company'){const c=companies.find(x=>x.id===a.refId);if(c)nm=c.name;}
  if(a.role==='admin')nm='통합관리자';
  acct={id:a.id,role:a.role,refType:a.refType||null,refId:a.refId||'',name:nm,defaultPw:!!dpw};
  roleKey=a.role==='admin'?'supervisor':a.role==='engineer'?'engineer':'manager';
  ROLE.write=CAP.write;ROLE.admin=CAP.write&&a.role==='admin';ROLE.site=CAP.write;
  ME.personId='';ME.name='';ME.org='';ME.grade='';
  if(a.refType==='person')applyPerson(a.refId);
  if((a.role==='engineer'||a.role==='client')&&!ME.name){ME.name=nm;if(a.refType==='company'||a.role==='client')ME.org=nm;}
  lsSet('last_id',a.id);applyScope();
  entered=true;$('#gate').hidden=true;document.body.classList.remove('gated');
  setRole(ROLES[roleKey].ko+' · '+nm);route={v:'dash'};renderNav();render();window.scrollTo(0,0);hashCable();hashSite();
}
