function pwCard(){
  const a=accounts.find(x=>x.id===acct.id);const msg=h('div');
  const idEl=h('input',{type:'text',autocapitalize:'none'});idEl.value=acct.id;if(acct.role!=='admin')idEl.disabled=true;
  const p0=h('input',{type:'password',autocomplete:'current-password'}),p1=h('input',{type:'password',autocomplete:'new-password'}),p2=h('input',{type:'password',autocomplete:'new-password'});
  const say=(m,e)=>msg.replaceChildren(h('div',{class:'note'+(e?' err':'')},m));
  const save=async()=>{
    if(!CAP.write){say('이 링크의 공유 권한이 보기 전용이라 변경할 수 없습니다. 통합관리자에게 요청하세요.',1);return;}
    const cur=await ICTMS.verifyPassword(p0.value);
    if(!cur){say('현재 비밀번호가 맞지 않습니다.',1);return;}
    const nid=(idEl.value||'').trim().toLowerCase();
    if(!validId(nid)){say('아이디는 영문 소문자·숫자·._- 3~20자로 입력하세요.',1);return;}
    if(nid!==acct.id&&accounts.some(x=>x.id===nid)){say('이미 사용 중인 아이디입니다.',1);return;}
    if(p1.value){if(p1.value.length<8){say('새 비밀번호는 8자 이상이어야 합니다.',1);return;}if(p1.value!==p2.value){say('새 비밀번호 확인이 다릅니다.',1);return;}}
    if(!p1.value&&nid===acct.id){say('바꿀 내용이 없습니다.',1);return;}
    try{await putAccount(nid,acct,p1.value||(a?null:p0.value),a);if(nid!==acct.id&&a)await db.collection('accounts').doc(acct.id).delete();
      acct.id=nid;if(p1.value)acct.defaultPw=false;lsSet('last_id',nid);p0.value=p1.value=p2.value='';say('저장했습니다. 다음 로그인부터 적용됩니다.');}
    catch(e){say('저장 실패: '+(e.code||e.message),1);}};
  return h('div',{class:'card'},h('h3',{},'로그인 정보'),acct.defaultPw?h('div',{class:'note err'},'초기 비밀번호를 쓰고 있습니다. 새 비밀번호로 바꾸세요.'):null,
    h('div',{class:'idp'},fld('아이디'+(acct.role==='admin'?'':' (변경 불가)'),idEl),fld('현재 비밀번호',p0),fld('새 비밀번호 (바꿀 때만)',p1),fld('새 비밀번호 확인',p2)),
    h('div',{class:'row',style:'margin-top:12px'},h('button',{class:'pri',onclick:save},'저장'),h('div',{class:'grow'}),msg));
}
