function twoStep(label,fn,armLabel){const b=h('button',{class:'dng'},label);let armed=false,t;
  b.addEventListener('click',()=>{if(!armed){armed=true;b.textContent=armLabel||'한 번 더 누르면 삭제';clearTimeout(t);t=setTimeout(()=>{armed=false;b.textContent=label;},3000);}else{clearTimeout(t);fn();}});return b;}
function selBox(obj,key,opts,ph,on){const el=h('select',{},h('option',{value:''},ph),...opts.map(([v,l])=>h('option',{value:v},l)));el.value=obj[key]||'';el.addEventListener('change',()=>{obj[key]=el.value;if(on)on();});return el;}
const SAMPLE_MEMOS=['육안 점검 결과 양호함','측정값 정상 범위 이내','관리주체 입회 확인','제조사 기준 확인 완료','교체 또는 수리 필요','추후 재점검 필요'];
function memoManager(owner,title,desc){
  const list=memos.filter(m=>m.owner===owner).sort((a,b)=>(a.text||'').localeCompare(b.text||'','ko'));
  const inp=h('input',{type:'text',placeholder:'예: 육안 점검 결과 양호함'});
  const add=async t=>{t=(t||'').trim();if(!t||memos.some(m=>m.owner===owner&&m.text===t))return;await db.collection('memos').doc(uid()).set({text:t,owner,createdAt:new Date().toISOString()});};
  inp.addEventListener('keydown',e=>{if(e.key==='Enter'){add(inp.value);inp.value='';}});
  const box=h('div',{class:'card'},h('h3',{},title),h('div',{class:'muted',style:'margin-bottom:10px'},desc),
    h('div',{class:'row'},h('div',{class:'grow'},inp),h('button',{class:'pri',onclick:async()=>{await add(inp.value);inp.value='';}},'추가')));
  list.forEach(m=>box.append(h('div',{class:'item',style:'align-items:center'},h('div',{class:'grow'},m.text),twoStep('삭제',()=>db.collection('memos').doc(m.id).delete()))));
  if(!list.length)box.append(h('div',{class:'row',style:'margin-top:10px'},h('button',{onclick:async()=>{for(const t of SAMPLE_MEMOS)await add(t);}},'예시 메모 넣기')));
  return box;}
