  f.addEventListener('change',()=>{const x=f.files[0];f.value='';if(!x)return;
    parseSiteXlsx(x,box,{auto:true,onDone:m=>{const w=m.get(s.name)||[...m.values()].find(v=>v.id===s.id);if(w){siteDraft={...clone(w.body),id:w.id};render();
      const n=h('div',{class:'note'},'엑셀 내용을 적용해 저장했습니다.');$('#app').prepend(n);setTimeout(()=>n.remove(),5000);}}});});
