function cnt(i){const c={ok:0,ng:0,na:0,total:0,done:0};
  for(const U of unitsOf(i)){itemsOf(U.no,i.type).forEach((_,k)=>{c.total++;const r=((i.res||{})[U.u+'-'+k]||{}).r;if(r){c[r]++;c.done++;}});}return c;}

