/* ---------- 자동 저장 ---------- */
let saveT=null,saving=false,dirty=false;
function touch(){if(!ROLE.write)return;dirty=true;setSave('저장 대기…');clearTimeout(saveT);saveT=setTimeout(flush,800);}
async function flush(){
  clearTimeout(saveT);
  while(saving)await new Promise(r=>setTimeout(r,150));
  if(!dirty||!cur)return;saving=true;dirty=false;
  try{const {isNew,...body}=cur;body.updatedAt=new Date().toISOString();await db.collection('inspections').doc(cur.id).set(body);cur.isNew=false;setSave('저장됨 '+new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}));}
  catch(e){dirty=true;setSave('저장 실패: '+(e.code||e.message));}
  saving=false;
}
function saveBtn(cls){const b=h('button',{class:cls||'',onclick:async()=>{if(!cur)return;dirty=true;await flush();const ok=!dirty;const o=b.textContent;b.textContent=ok?'✔ 저장됨':'저장 실패';setTimeout(()=>{b.textContent='저장';},1600);}},'저장');return b;}
function setSave(t){const e=$('#savestate');if(e)e.textContent=t;}

/* ---------- 점검 Sheet ---------- */
function vSheet(app){
  if(!cur){go('insp');return;}
  const c=cnt(cur),pct=c.total?Math.round(c.done/c.total*100):0;
  app.append(h('div',{class:'card'},h('div',{class:'row'},
    h('button',{onclick:async()=>{setResume(null);await flush();go('insp');}},'나가기'),h('button',{onclick:()=>navTo('siteview',{id:cur.siteId})},'사이트 정보'),h('div',{class:'grow'}),h('span',{class:'muted sm',id:'savestate'},''),saveBtn('pri')),
    h('div',{style:'margin-top:12px'},h('b',{style:'font-size:17px'},siteName(cur.siteId)),h('div',{class:'row',style:'gap:8px;margin-top:4px'},h('span',{class:'pill pri'},TYPES[cur.type]),h('span',{class:'muted'},cur.date+' · '+cur.engineer.name+(cur.engineer.org?' · '+cur.engineer.org:'')))),
    h('div',{class:'row',style:'margin-top:8px'},h('div',{class:'grow'},h('div',{class:'bar'},h('i',{style:'width:'+pct+'%'}))),h('span',{class:'muted'},c.done+' / '+c.total+' 항목'))));
  if(sheet.mode==='areas')areasView(app);else stepView(app);
}
function getGps(){
  const done=m=>alert2(m);
  if(!navigator.geolocation){done('이 화면에서는 위치 기능을 쓸 수 없습니다. 좌표를 직접 입력하세요.');return;}
  try{navigator.geolocation.getCurrentPosition(p=>{cur.gps=p.coords.latitude.toFixed(6)+', '+p.coords.longitude.toFixed(6);touch();render();},
    ()=>done('위치 권한을 받을 수 없습니다(이 화면에서는 제한됨). 좌표를 직접 입력하세요.'),{timeout:8000});}catch(e){done('위치 기능을 쓸 수 없습니다. 좌표를 직접 입력하세요.');}
}
function areaProg(U){const its=itemsOf(U.no,cur.type);let d=0,ng=0;its.forEach((_,k)=>{const r=((cur.res[U.u+'-'+k])||{}).r;if(r)d++;if(r==='ng')ng++;});return{d,t:its.length,ng};}
function strip(U,nav){const its=itemsOf(U.no,cur.type);return h('div',{class:'strip'+(nav?' nav':'')},...its.map((x,k)=>{const r=(cur.res[U.u+'-'+k]||{}).r||'';
  return h('i',{class:r+(nav&&k===sheet.idx?' cur':''),title:(k+1)+'. '+x.t,onclick:nav?()=>{sheet.idx=k;render();}:undefined});}));}
